hero:
.hero {
  color: rgb(255, 255, 255);
}

.hero h1 {
  font-size: 48px;
  font-weight: 400;
  font-family: "AvenirNext forINTUIT", "Mulish Variable", mulish-fallback, arial, sans-serif;
  line-height: 60px;
  color: rgb(255, 255, 255);
  margin: 0px 0px 20px;
}

.hero p {
  font-size: 20px;
  font-family: "AvenirNext forINTUIT", "Mulish Variable", mulish-fallback, arial, sans-serif;
  line-height: 28px;
  color: rgb(230, 238, 246);
  margin: 0px 0px 40px;
}

.hero a {
  color: rgb(13, 51, 63);
  font-size: 16px;
  font-weight: 600;
  text-decoration: none;
}

.hero a.button:any-link {
  background-color: rgb(255, 255, 255);
  color: rgb(13, 51, 63);
  padding: 0px 30px;
  border: 2px solid rgb(255, 255, 255);
  border-radius: 4px;
  font-size: 16px;
  font-weight: 600;
  display: inline-block;
}

.hero img {
  object-fit: cover;
  border-radius: 12px;
  width: 100%;
}

.hero > div {
  display: grid;
  gap: 48px;
  align-items: start;
  grid-template-columns: 672px 640px;
}

tabs:
.tabs {
  background-color: rgb(239, 244, 249);
  color: rgb(33, 38, 42);
  border-radius: 4px;
}

.tabs h3 {
  font-size: 34px;
  font-weight: 600;
  font-family: "AvenirNext forINTUIT", "Mulish Variable", mulish-fallback, arial, sans-serif;
  line-height: 44px;
  color: rgb(57, 58, 61);
  margin: 0px 0px 24px;
}

.tabs p {
  font-size: 16px;
  font-family: "AvenirNext forINTUIT", "Mulish Variable", mulish-fallback, arial, sans-serif;
  line-height: 20.8px;
  color: rgb(57, 58, 61);
  margin: 0px 0px 16px;
}

.tabs a.button:any-link {
  color: rgba(57, 58, 61, 0.25);
  padding: 1px 6px;
  border: 0px none rgba(57, 58, 61, 0.25);
  font-size: 16px;
  font-weight: 400;
  display: inline-block;
}

.tabs img {
  width: 100%;
}

.tabs > div {
  display: flex;
}

.tabs > div > div {
  flex: 0 0 auto;
  padding: 1px 6px;
}

